<?php
namespace Tests\Feature;
use App\Accounting\{AccountingService,Money,ProjectService,Reports};
use App\Models\User;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use Tests\TestCase;
class AccountingTest extends TestCase {
 use RefreshDatabase;
 protected User $manager;protected AccountingService $service;protected int $project;protected int $owner;protected int $owner2;protected int $supplier;protected int $bank;protected int $contract;
 protected function setUp():void {
  parent::setUp();$this->service=app(AccountingService::class);$this->manager=User::factory()->create();$org=DB::table('organizations')->insertGetId(['name'=>'سازمان آزمایشی']);DB::table('organization_members')->insert(['organization_id'=>$org,'user_id'=>$this->manager->id,'role'=>'manager']);
  $p=app(ProjectService::class)->create($this->manager,['name'=>'پروژه آزمایشی','code'=>'T1','commencement_date'=>'2026-11-01','history_mode'=>'opening','budget'=>'1000000000']);$this->project=$p->id;
  $this->owner=DB::table('parties')->insertGetId(['organization_id'=>$org,'name'=>'مالک اول','identity_code'=>'test1']);$this->owner2=DB::table('parties')->insertGetId(['organization_id'=>$org,'name'=>'مالک دوم','identity_code'=>'test2']);$this->supplier=DB::table('parties')->insertGetId(['organization_id'=>$org,'name'=>'فروشنده آزمایشی','identity_code'=>'test3']);$this->bank=DB::table('bank_accounts')->insertGetId(['project_id'=>$p->id,'name'=>'بانک آزمایشی']);
  $this->contract=DB::table('contracts')->insertGetId(['project_id'=>$p->id,'number'=>'C1','kind'=>'ownership','date'=>'2026-11-01','description'=>'قرارداد آزمایشی']);
  app(ProjectService::class)->rule($this->manager,$p->id,$this->ruleData(),true);
 }
 private function ruleData(array $changes=[]):array{return array_replace(['contract_id'=>$this->contract,'effective_date'=>'2026-11-01','posting_date'=>'2026-11-03','fee_bps'=>1000,'shares'=>[$this->owner=>5000,$this->owner2=>5000],'mode'=>'prospective'],$changes);}
 private function draft(string $kind,array $data,string $date='2026-11-03'):object{return $this->service->draft($this->manager,$this->project,['kind'=>$kind,'date'=>$date,'description'=>'سند آزمایشی','idempotency_key'=>(string)Str::uuid(),'data'=>$data]);}
 private function postDoc(string $kind,array $data,string $date='2026-11-03'):object{$doc=$this->draft($kind,$data,$date);return $this->service->approve($this->manager,$this->project,$doc->id);}
 private function invoice(int $amount=1000000,?int $supplier=null,string $date='2026-11-03'):object{return $this->postDoc('invoice',['party_id'=>$supplier??$this->supplier,'items'=>[['description'=>'مصالح آزمایشی','amount'=>$amount,'fee_eligible'=>true]]],$date);}
 private function fund(int $amount=2000000):void{$this->postDoc('contribution',['party_id'=>$this->owner,'bank_id'=>$this->bank,'amount'=>$amount]);}
 private function settlement(object $invoice,int $amount,?int $supplier=null):array{return ['party_id'=>$supplier??$this->supplier,'bank_id'=>$this->bank,'allocations'=>[['invoice_id'=>$invoice->id,'amount'=>$amount]]];}
 private function balance(string $a,?int $party=null):int{return $this->service->balance($this->project,$a,$party);}
 public function test_unpaid_invoice_accrues_fee_allocations_and_is_idempotent():void {
  $i=$this->invoice();$this->assertSame(1000000,$this->balance('cost'));$this->assertSame(-1000000,$this->balance('supplier'));$this->assertSame(100000,$this->balance('fee_cost'));$this->assertSame(-100000,$this->balance('fee_payable'));$this->assertSame(1100000,(int)DB::table('owner_cost_allocations')->sum('amount'));
  $this->service->approve($this->manager,$this->project,$i->id);$this->assertSame(1,DB::table('journal_entries')->count());$this->assertSame(1100000,app(Reports::class)->summary($this->project)['cost']);
 }
 public function test_partial_and_full_payments_do_not_duplicate_cost_or_fee():void {
  $this->fund();$i=$this->invoice();$this->postDoc('payment',$this->settlement($i,400000));$this->assertSame(-600000,$this->balance('supplier'));$this->postDoc('payment',$this->settlement($i,600000));$this->assertSame(0,$this->balance('supplier'));$this->assertSame(1000000,$this->balance('cost'));$this->assertSame(100000,$this->balance('fee_cost'));$this->assertSame(1000000,$this->balance('bank'));
 }
 public function test_invoice_reversal_reverses_fee_and_owner_allocations():void {$i=$this->invoice();$this->service->reverse($this->manager,$this->project,$i->id,'2026-11-04');$this->service->reverse($this->manager,$this->project,$i->id,'2026-11-04');$this->assertSame(0,$this->balance('cost'));$this->assertSame(0,$this->balance('fee_cost'));$this->assertSame(0,(int)DB::table('owner_cost_allocations')->sum('amount'));}
 public function test_owner_supplier_does_not_automatically_create_contribution_and_offset_is_separate():void {
  $i=$this->invoice(1000000,$this->owner);$this->assertSame(0,$this->balance('contribution'));$offset=$this->postDoc('offset',$this->settlement($i,400000,$this->owner));$this->service->approve($this->manager,$this->project,$offset->id);$this->assertSame(-600000,$this->balance('supplier',$this->owner));$this->assertSame(-400000,$this->balance('contribution',$this->owner));$this->assertSame(0,$this->balance('bank'));$this->service->reverse($this->manager,$this->project,$offset->id,'2026-11-04');$this->assertSame(-1000000,$this->balance('supplier',$this->owner));$this->assertSame(0,$this->balance('contribution'));
 }
 public function test_excessive_offset_is_rejected_atomically():void {$i=$this->invoice(100,$this->owner);$this->expectException(ValidationException::class);try{$this->postDoc('offset',$this->settlement($i,101,$this->owner));}finally{$this->assertSame(1,DB::table('documents')->count());$this->assertSame(-100,$this->balance('supplier'));}}
 public function test_direct_owner_payment_has_no_bank_or_duplicate_expense():void {$i=$this->invoice();$this->postDoc('direct_payment',$this->settlement($i,500000)+['owner_id'=>$this->owner]);$this->assertSame(-500000,$this->balance('supplier'));$this->assertSame(-500000,$this->balance('contribution'));$this->assertSame(0,$this->balance('bank'));$this->assertSame(1000000,$this->balance('cost'));}
 public function test_personal_payment_and_combined_settlement_keep_subledgers_separate():void {
  $this->fund();$i=$this->invoice();$this->postDoc('personal_payment',$this->settlement($i,300000));$this->assertSame(-300000,$this->balance('reimbursement'));$this->assertSame(-100000,$this->balance('fee_payable'));$this->postDoc('settlement',['bank_id'=>$this->bank,'fee_amount'=>100000,'reimbursement_amount'=>300000]);$this->assertSame(0,$this->balance('reimbursement'));$this->assertSame(0,$this->balance('fee_payable'));$this->assertSame(1000000,$this->balance('cost'));$this->assertSame(1600000,$this->balance('bank'));
 }
 public function test_incoming_check_only_recognizes_contribution_on_clearing_once():void {
  $c=$this->postDoc('incoming_check',['party_id'=>$this->owner,'bank_id'=>$this->bank,'amount'=>500000,'number'=>'IN-1','bank_name'=>'بانک آزمایشی','due_date'=>'2026-11-05']);$this->assertSame(0,$this->balance('bank'));$this->assertSame(0,$this->balance('contribution'));$this->assertSame(500000,$this->balance('incoming_check'));$this->service->checkEvent($this->manager,$this->project,$c->id,'cleared','2026-11-05');$this->service->checkEvent($this->manager,$this->project,$c->id,'cleared','2026-11-05');$this->assertSame(500000,$this->balance('bank'));$this->assertSame(-500000,$this->balance('contribution'));$this->assertSame(0,$this->balance('incoming_check'));
 }
 public function test_outgoing_check_delivery_clearing_and_invalid_transition():void {
  $this->fund();$i=$this->invoice();$c=$this->postDoc('outgoing_check',$this->settlement($i,500000)+['number'=>'OUT-1','bank_name'=>'بانک آزمایشی','due_date'=>'2026-11-05']);$this->assertSame(2000000,$this->balance('bank'));$this->assertSame(-500000,$this->balance('supplier'));$this->assertSame(-500000,$this->balance('outgoing_check'));$this->service->checkEvent($this->manager,$this->project,$c->id,'cleared','2026-11-05');$this->assertSame(1500000,$this->balance('bank'));$this->assertSame(0,$this->balance('outgoing_check'));$this->expectException(ValidationException::class);$this->service->checkEvent($this->manager,$this->project,$c->id,'returned','2026-11-06');
 }
 public function test_returned_outgoing_check_restores_supplier_claim():void {$i=$this->invoice();$c=$this->postDoc('outgoing_check',$this->settlement($i,500000)+['number'=>'OUT-2','bank_name'=>'بانک آزمایشی','due_date'=>'2026-11-05']);$this->service->checkEvent($this->manager,$this->project,$c->id,'returned','2026-11-05');$this->assertSame(-1000000,$this->balance('supplier'));$this->assertSame(0,$this->balance('outgoing_check'));$this->assertSame(0,$this->balance('bank'));}
 public function test_retroactive_amendment_posts_difference_and_keeps_original_journal():void {
  $i=$this->invoice();$before=DB::table('journal_lines')->get()->toJson();$d=$this->ruleData(['mode'=>'retroactive','fee_bps'=>2000,'shares'=>[$this->owner=>6000,$this->owner2=>4000]]);$preview=app(ProjectService::class)->rule($this->manager,$this->project,$d);$this->assertSame(100000,$preview['changes'][0]['fee_difference']);app(ProjectService::class)->rule($this->manager,$this->project,$d,true);$this->assertSame(200000,$this->balance('fee_cost'));$this->assertSame(1200000,(int)DB::table('owner_cost_allocations')->sum('amount'));$this->assertSame(720000,(int)DB::table('owner_cost_allocations')->where('party_id',$this->owner)->sum('amount'));$this->assertSame($before,DB::table('journal_lines')->where('journal_entry_id',1)->get()->toJson());$this->assertSame(0,app(Reports::class)->summary($this->project)['reconciliation']['allocation_difference']);
 }
 public function test_prospective_amendment_preserves_prior_allocations():void {
  $this->invoice(1000000,null,'2026-11-02');$d=$this->ruleData(['effective_date'=>'2026-11-04','fee_bps'=>2000,'shares'=>[$this->owner=>6000,$this->owner2=>4000]]);app(ProjectService::class)->rule($this->manager,$this->project,$d,true);$this->invoice(1000000,null,'2026-11-04');$this->assertSame(300000,$this->balance('fee_cost'));$this->assertSame(1270000,(int)DB::table('owner_cost_allocations')->where('party_id',$this->owner)->sum('amount'));
 }
 public function test_rounding_and_invalid_percentages():void {$this->assertSame([1=>1,2=>1,3=>0],Money::allocate(2,[1=>3334,2=>3333,3=>3333]));$this->assertSame(1,Money::fee(5,1000));$this->expectException(ValidationException::class);Money::allocate(100,[1=>9000]);}
 public function test_opening_is_balanced_and_cannot_be_posted_twice():void {
  $data=['reconciled'=>true,'lines'=>[['account'=>'bank','debit'=>'1000','credit'=>'0','bank_id'=>$this->bank],['account'=>'contribution','debit'=>'0','credit'=>'1000','party_id'=>$this->owner]]];$this->postDoc('opening',$data,'2026-11-01');$this->assertSame(1000,$this->balance('bank'));$this->assertSame(-1000,$this->balance('contribution'));$this->expectException(ValidationException::class);$this->draft('opening',$data,'2026-11-01');
 }
 public function test_unbalanced_opening_rolls_back_everything():void {$this->expectException(ValidationException::class);try{$this->postDoc('opening',['reconciled'=>true,'lines'=>[['account'=>'bank','debit'=>1000,'credit'=>0,'bank_id'=>$this->bank],['account'=>'opening_control','debit'=>0,'credit'=>999]]],'2026-11-01');}finally{$this->assertSame(0,DB::table('documents')->count());}}
 public function test_owner_cannot_write_and_other_tenants_cannot_read():void {
  $owner=User::factory()->create();$org=DB::table('projects')->find($this->project)->organization_id;DB::table('organization_members')->insert(['organization_id'=>$org,'user_id'=>$owner->id,'role'=>'member']);DB::table('project_members')->insert(['project_id'=>$this->project,'user_id'=>$owner->id,'role'=>'owner']);$this->actingAs($owner)->get('/projects/'.$this->project)->assertOk()->assertSee('دسترسی مالک');$this->postJson('/api/v1/projects/'.$this->project.'/documents',['kind'=>'invoice','date'=>'2026-11-03','description'=>'forbidden','idempotency_key'=>'owner','data'=>[]])->assertForbidden();$outsider=User::factory()->create();$this->actingAs($outsider)->get('/projects/'.$this->project)->assertForbidden();$this->getJson('/api/v1/projects/'.$this->project.'/reports')->assertForbidden();
 }
 public function test_posted_journal_cannot_be_changed_in_database():void {$this->invoice();$this->expectException(\Illuminate\Database\QueryException::class);DB::table('journal_lines')->where('id',1)->update(['debit'=>9]);}
 public function test_closed_period_rejects_posting_and_negative_bank_is_rejected():void {
  $i=$this->invoice();$this->expectException(ValidationException::class);try{$this->postDoc('payment',$this->settlement($i,100));}finally{$this->assertSame(0,$this->balance('bank'));}
 }
 public function test_closed_fiscal_year_blocks_approval_without_journal():void {$d=$this->draft('invoice',['party_id'=>$this->supplier,'items'=>[['description'=>'test','amount'=>100]]]);DB::table('fiscal_years')->where('project_id',$this->project)->update(['closed'=>true]);$this->expectException(ValidationException::class);try{$this->service->approve($this->manager,$this->project,$d->id);}finally{$this->assertSame(0,DB::table('journal_entries')->count());}}
 public function test_dashboard_reports_and_document_preview_render():void {$this->fund();$i=$this->invoice();$this->actingAs($this->manager)->get('/projects/'.$this->project)->assertOk()->assertSee('هزینه کل پروژه');$this->get('/projects/'.$this->project.'/reports')->assertOk()->assertSee('تراز آزمایشی');$this->get('/projects/'.$this->project.'/documents/'.$i->id)->assertOk()->assertSee('ثبت‌های دفتر حساب');$this->get('/projects/'.$this->project.'/reports?export=csv')->assertOk()->assertDownload('ledger.csv');}
 public function test_every_journal_and_owner_allocation_reconciles():void {$this->fund();$i=$this->invoice(1234567);$this->postDoc('payment',$this->settlement($i,12345));$r=app(Reports::class)->summary($this->project);$this->assertSame(0,$r['reconciliation']['unbalanced_journals']);$this->assertSame(0,$r['reconciliation']['trial_difference']);$this->assertSame(0,$r['reconciliation']['allocation_difference']);}
}
